<script>
(()=>{const search=document.getElementById('cv-country-search'),filter=document.getElementById('cv-country-filter');if(!search||!filter)return;const update=()=>{const q=search.value.trim().toLowerCase(),mode=filter.value;document.querySelectorAll('.cv-country-row').forEach(row=>{const text=row.dataset.search||'',enabled=row.dataset.vendorEnabled==='1';row.hidden=!(text.includes(q)&&(mode==='all'||(mode==='enabled'&&enabled)||(mode==='disabled'&&!enabled)))})};search.addEventListener('input',update);filter.addEventListener('change',update)})();
</script>
